_COMPARISON_OPS = {"=", "!=", "<", "<=", ">", ">="}


def _compare(op, left, right):
    if left is None or right is None:
        return None
    if op == "=":
        return left == right
    if op == "!=":
        return left != right
    if op == "<":
        return left < right
    if op == "<=":
        return left <= right
    if op == ">":
        return left > right
    if op == ">=":
        return left >= right
    return False


def _eval_condition(cond, get_operand, ctx):
    op = cond[0]

    if op == "and":
        left = _eval_condition(cond[1], get_operand, ctx)
        if left is False:
            return False
        right = _eval_condition(cond[2], get_operand, ctx)
        if right is False:
            return False
        if left is None or right is None:
            return None
        return True

    if op == "or":
        left = _eval_condition(cond[1], get_operand, ctx)
        if left is True:
            return True
        right = _eval_condition(cond[2], get_operand, ctx)
        if right is True:
            return True
        if left is None or right is None:
            return None
        return False

    if op == "not":
        val = _eval_condition(cond[1], get_operand, ctx)
        if val is None:
            return None
        return not val

    if op == "is_null":
        return get_operand(cond[1], ctx) is None

    if op == "in":
        values = cond[2]
        if not values:
            return False

        val = get_operand(cond[1], ctx)
        if val is None:
            return None

        has_null = False
        for item in values:
            if item is None:
                has_null = True
            elif item == val:
                return True

        return None if has_null else False

    if op == "between":
        val = get_operand(cond[1], ctx)
        left = _compare(">=", val, cond[2])
        if left is False:
            return False
        right = _compare("<=", val, cond[3])
        if right is False:
            return False
        if left is None or right is None:
            return None
        return True

    left = get_operand(cond[1], ctx)
    right = get_operand(cond[2], ctx)
    return _compare(op, left, right)


def _operand_value_row(operand, ctx):
    if isinstance(operand, (list, tuple)):
        if not operand:
            return None
        kind = operand[0]
        if kind == "col":
            return ctx[operand[1]]
        if kind == "val":
            return operand[1]
        return None
    return operand


def _aggregate_value(group, func, arg, agg_index):
    if func == "count" and arg == "*":
        return group[1]

    idx = agg_index.get((func, arg))
    if idx is None:
        return 0 if func in ("count", "count_distinct") else None

    acc = group[2][idx]

    if func == "count":
        return acc
    if func == "count_distinct":
        return len(acc)
    if func == "sum":
        return acc[0] if acc[1] else None
    if func == "avg":
        return acc[0] // acc[1] if acc[1] else None

    # min / max
    return acc


def _operand_value_group(operand, ctx):
    if isinstance(operand, (list, tuple)):
        if not operand:
            return None

        kind = operand[0]
        if kind == "val":
            return operand[1]

        group, group_col_index, agg_index = ctx

        if kind == "col":
            idx = group_col_index.get(operand[1])
            if idx is None:
                return None
            return group[0][idx]

        if kind == "agg":
            return _aggregate_value(group, operand[1], operand[2], agg_index)

        return None

    return operand


def _init_acc(func, arg):
    if func == "count" and arg == "*":
        return None
    if func == "count":
        return 0
    if func == "count_distinct":
        return set()
    if func in ("sum", "avg"):
        return [0, 0]
    return None


def _update_group_with_row(group, row, non_star_aggs):
    group[1] += 1

    if not non_star_aggs:
        return

    accs = group[2]
    for idx, func, arg in non_star_aggs:
        val = row[arg]
        if val is None:
            continue

        if func == "count":
            accs[idx] += 1
        elif func == "count_distinct":
            accs[idx].add(val)
        elif func in ("sum", "avg"):
            acc = accs[idx]
            acc[0] += val
            acc[1] += 1
        elif func == "min":
            cur = accs[idx]
            if cur is None or val < cur:
                accs[idx] = val
        elif func == "max":
            cur = accs[idx]
            if cur is None or val > cur:
                accs[idx] = val


def _collect_operand_agg(operand, add_agg):
    if isinstance(operand, (list, tuple)) and operand and operand[0] == "agg":
        add_agg(operand[1], operand[2])


def _collect_condition_aggs(cond, add_agg):
    if not isinstance(cond, (list, tuple)) or not cond:
        return

    op = cond[0]

    if op in ("and", "or"):
        _collect_condition_aggs(cond[1], add_agg)
        _collect_condition_aggs(cond[2], add_agg)
    elif op == "not":
        _collect_condition_aggs(cond[1], add_agg)
    elif op in _COMPARISON_OPS:
        _collect_operand_agg(cond[1], add_agg)
        _collect_operand_agg(cond[2], add_agg)
    elif op == "is_null":
        _collect_operand_agg(cond[1], add_agg)
    elif op == "in":
        _collect_operand_agg(cond[1], add_agg)
    elif op == "between":
        _collect_operand_agg(cond[1], add_agg)


def _apply_order_by(result, order_by):
    for spec in reversed(order_by):
        key_name = spec[0]
        direction = spec[1]
        nulls = spec[2] if len(spec) > 2 else None

        desc = direction == "desc"
        if nulls in ("first", "last"):
            null_first = nulls == "first"
        else:
            # NULL is treated as smaller than everything else.
            null_first = not desc

        if desc:
            if null_first:
                def key_func(row, k=key_name):
                    v = row.get(k)
                    if v is None:
                        return (1,)
                    return (0, v)

                result.sort(key=key_func, reverse=True)
            else:
                def key_func(row, k=key_name):
                    v = row.get(k)
                    if v is None:
                        return (0,)
                    return (1, v)

                result.sort(key=key_func, reverse=True)
        else:
            if null_first:
                def key_func(row, k=key_name):
                    v = row.get(k)
                    if v is None:
                        return (0,)
                    return (1, v)

                result.sort(key=key_func)
            else:
                def key_func(row, k=key_name):
                    v = row.get(k)
                    if v is None:
                        return (1,)
                    return (0, v)

                result.sort(key=key_func)

    return result


def run_query(rows: list[dict], query: dict) -> list[dict]:
    select = query.get("select", [])
    where = query.get("where")
    group_by = query.get("group_by") or []
    having = query.get("having")
    distinct = query.get("distinct")
    order_by = query.get("order_by")
    offset = query.get("offset")
    limit = query.get("limit")

    needed_aggs = []
    agg_index = {}

    def add_agg(func, arg):
        key = (func, arg)
        if key not in agg_index:
            agg_index[key] = len(needed_aggs)
            needed_aggs.append(key)

    select_meta = []
    for item in select:
        if isinstance(item, (list, tuple)):
            func = item[0]
            arg = item[1]
            select_meta.append(("agg", func, arg, f"{func}({arg})"))
            add_agg(func, arg)
        else:
            select_meta.append(("col", item, item))

    if having is not None:
        _collect_condition_aggs(having, add_agg)

    non_star_aggs = []
    for i, (func, arg) in enumerate(needed_aggs):
        if not (func == "count" and arg == "*"):
            non_star_aggs.append((i, func, arg))

    grouped = bool(group_by) or bool(needed_aggs) or having is not None

    if not grouped:
        result = []

        if where is None:
            for row in rows:
                out = {}
                for meta in select_meta:
                    if meta[0] == "col":
                        out[meta[2]] = row[meta[1]]
                    else:
                        out[meta[3]] = None
                result.append(out)
        else:
            for row in rows:
                if _eval_condition(where, _operand_value_row, row) is True:
                    out = {}
                    for meta in select_meta:
                        if meta[0] == "col":
                            out[meta[2]] = row[meta[1]]
                        else:
                            out[meta[3]] = None
                    result.append(out)

    else:
        group_col_index = {name: i for i, name in enumerate(group_by)}
        groups = {}

        if not group_by:
            single_group = [(), 0, [_init_acc(func, arg) for func, arg in needed_aggs]]
            groups[()] = single_group

            if where is None:
                for row in rows:
                    _update_group_with_row(single_group, row, non_star_aggs)
            else:
                for row in rows:
                    if _eval_condition(where, _operand_value_row, row) is True:
                        _update_group_with_row(single_group, row, non_star_aggs)
        else:
            if where is None:
                for row in rows:
                    key = tuple(row[c] for c in group_by)
                    group = groups.get(key)
                    if group is None:
                        group = [key, 0, [_init_acc(func, arg) for func, arg in needed_aggs]]
                        groups[key] = group
                    _update_group_with_row(group, row, non_star_aggs)
            else:
                for row in rows:
                    if _eval_condition(where, _operand_value_row, row) is True:
                        key = tuple(row[c] for c in group_by)
                        group = groups.get(key)
                        if group is None:
                            group = [key, 0, [_init_acc(func, arg) for func, arg in needed_aggs]]
                            groups[key] = group
                        _update_group_with_row(group, row, non_star_aggs)

        group_list = list(groups.values())

        if having is not None:
            kept = []
            for group in group_list:
                ctx = (group, group_col_index, agg_index)
                if _eval_condition(having, _operand_value_group, ctx) is True:
                    kept.append(group)
            group_list = kept

        result = []
        for group in group_list:
            out = {}
            key_values = group[0]

            for meta in select_meta:
                if meta[0] == "col":
                    name = meta[1]
                    idx = group_col_index.get(name)
                    out[meta[2]] = key_values[idx] if idx is not None else None
                else:
                    func = meta[1]
                    arg = meta[2]
                    out[meta[3]] = _aggregate_value(group, func, arg, agg_index)

            result.append(out)

    if distinct:
        seen = set()
        unique = []
        for out in result:
            marker = tuple(out.values())
            if marker not in seen:
                seen.add(marker)
                unique.append(out)
        result = unique

    if order_by:
        _apply_order_by(result, order_by)

    start = offset if offset is not None else 0
    if limit is None:
        if start:
            result = result[start:]
    else:
        result = result[start:start + limit]

    return result
